 const labels=Object.freeze(Object.fromEntries(entries.split('\n').map(row=>row.split('|'))));
 function short(value,locale=root.JeiReportI18n.language){
  const name=root.JeiReportI18n.original(String(value)).trim();
  if(locale!=='en')return name;
  if(labels[name])return labels[name];
  // Keep the original sequence markers and numeric ranges. They distinguish
  // different skill checks; never shorten by blindly dropping parentheses.
  const sequence=name.match(/^(.*?)\s*([①②③])$/);
  if(sequence)return short(sequence[1],'en')+' '+sequence[2];
  const range=name.match(/^(모임의 크기 비교|수와 숫자|순서와 크기 비교|모으기와 가르기|수의 순서)\((\d+)\)$/);
  if(range)return labels[range[1]]+' ('+range[2]+')';
  return root.JeiReportI18n.t(name,'en');
 }
 root.JeiReportTopics=Object.freeze({short});
